export function funnel(events,steps,{idKey='userId'}={}){const reached=new Map();for(const s of steps)reached.set(s,new Set());for(const e of events??[])if(reached.has(e.event)&&e[idKey]!=null)reached.get(e.event).add(e[idKey]);let prev=null;return steps.map(s=>{const count=reached.get(s).size;const rate=prev==null?1:(prev?count/prev:0);prev=count;return{step:s,count,conversionFromPrevious:rate};});}
